class Solution {
  public int[] largestPower(int[] nums) {
    int n = nums.length;
    int[] elems = nums.clone();
    List<Integer> ends = new ArrayList<>();
    ends.add(n);
    int[] power = new int[15];
    for (int i = 0; i < 15; i++) {
      int bit = 14 - i;
      int prefix = 0, start = 0;
      boolean split = false;
      for (int g = 0; g < ends.size() && !split; g++) {
        int end = ends.get(g), count = 0;
        for (int t = start; t < end; t++) if ((elems[t] >> bit & 1) != 0) count++;
        if (count == end - start) {
          prefix += count;
        } else {
          // move the elements with the bit set to the front of the group
          int write = start;
          for (int t = start; t < end; t++) {
            if ((elems[t] >> bit & 1) != 0) {
              int tmp = elems[write];
              elems[write] = elems[t];
              elems[t] = tmp;
              write++;
            }
          }
          prefix += count;
          if (count > 0) ends.add(g, start + count);
          split = true;
        }
        start = end;
      }
      power[i] = prefix;
    }
    return power;
  }
}
